async function promptFeatureSelection(features, message) {
    const answer = await safePrompt([
        {
            type: 'list',
            name: 'selectedFeature',
            message,
            choices: features.map(feature => ({
                name: `${feature.active ? '✅' : '❌'} ${feature.title}`,
                value: feature
            }))
        }
    ]);
    return answer?.selectedFeature || null;
}
