        console.log(`\nUsage: lua features ${normalizedAction} --feature-name <name>`);
        if (features.length > 0) {
            console.log('\nAvailable features:');
            features.forEach(f => console.log(`  - ${f.name} (${f.title})`));
        }
        throw new Error("Operation failed");
